{
  "findings": [
    {
      "check_id": "CKV_AZURE_224",
      "title": "Ledger feature not enabled",
      "resource": "azurerm_mssql_database.trading_database",
      "severity": "MEDIUM",
      "explanation": "The Ledger feature is not enabled, which is a risk for databases requiring cryptographic proof and nonrepudiation of data integrity. This could lead to tampering or lack of auditability for sensitive data."
    },
    {
      "check_id": "CKV_AZURE_229",
      "title": "Zone redundancy not enabled",
      "resource": "azurerm_mssql_database.trading_database",
      "severity": "MEDIUM",
      "explanation": "Zone redundancy is disabled, which makes the database vulnerable to availability issues in case of a failure in a single availability zone."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_database\" \"trading_database\" {\n  name           = \"trading-database\"\n  server_id      = azurerm_mssql_server.trading_sql_server.id\n  collation      = \"SQL_Latin1_General_CP1_CI_AS\"\n  license_type   = \"LicenseIncluded\"\n  max_size_gb    = 100\n  sku_name       = \"S2\"\n  zone_redundant = true\n  ledger_enabled = true\n}",
  "fix_summary": "Enabled the Ledger feature to ensure cryptographic proof and nonrepudiation of data integrity. Enabled zone redundancy to improve database availability and resilience against zone failures."
}
